def google_search(api_key, q, gl=None, hl=None, location=None, num=None, page=None, type=None, autocorrect=None, time_range=None, **_extra):
    import json, os, datetime, time, re, uuid, hashlib, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0418000" if __import__("os").path.isdir("./environment_mix/0418000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"
    usage_day = now.date().isoformat()

    # Helpers
    def _ms():
        return int((time.time() - t0) * 1000)

    def _new_id(prefix):
        # deterministic-ish, readable, uppercase
        token = base64.b32encode(uuid.uuid4().bytes).decode("ascii").rstrip("=")
        return f"{prefix}_{token}"

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    def _json_obj_size_ok(obj, limit_bytes=65536):
        try:
            b = json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
            return len(b) <= limit_bytes
        except Exception:
            return False

    def _auth_api_key(raw):
        if not isinstance(raw, str) or not raw.strip():
            return None, _err("UNAUTHORIZED", "Missing or invalid api_key.")
        raw = raw.strip()
        keys = _load("api_keys.json")

        # authenticate by id, key_prefix, or full raw if it begins with prefix; never compare to key_hash
        candidates = []
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("id") == raw:
                candidates.append(k)
            elif isinstance(k.get("key_prefix"), str) and raw.startswith(k["key_prefix"]):
                candidates.append(k)

        if not candidates:
            return None, _err("UNAUTHORIZED", "api_key not found.")

        # choose an active key if possible; otherwise choose first match for better error specificity
        chosen = None
        for k in candidates:
            if k.get("status") == "active":
                chosen = k
                break
        if chosen is None:
            chosen = candidates[0]
        return chosen, None

    def _log_request(api_key_id, request_payload, response_payload=None, error_payload=None, search_query_id=None, scrape_job_id=None):
        logs = _load("request_logs.json")
        entry = {
            "id": _new_id("reqlog"),
            "api_key_id": api_key_id,
            "tool_name": "google_search",
            "search_query_id": search_query_id,
            "scrape_job_id": None,
            "request_payload": request_payload if isinstance(request_payload, dict) else {},
            "response_payload": response_payload,
            "error_payload": error_payload,
            "latency_ms": max(0, _ms()),
            "client_ip": None,
            "user_agent": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        logs.append(entry)
        _save("request_logs.json", logs)
        return entry

    # Validate inputs
    if not isinstance(api_key, str):
        # can't attribute log without a key; no log
        return _err("VALIDATION_ERROR", "api_key must be a string.")
    if not isinstance(q, str) or not q.strip():
        key_row, _ = _auth_api_key(api_key)
        if key_row:
            _log_request(key_row["id"], {"api_key": api_key, "q": q, "gl": gl, "hl": hl, "location": location, "num": num, "page": page, "type": type, "autocorrect": autocorrect, "time_range": time_range},
                         error_payload=_err("VALIDATION_ERROR", "q must be a non-empty string.")["error"])
        return _err("VALIDATION_ERROR", "q must be a non-empty string.")

    if gl is not None and not isinstance(gl, str):
        key_row, e = _auth_api_key(api_key)
        if key_row:
            _log_request(key_row["id"], {"api_key": api_key, "q": q, "gl": gl, "hl": hl, "location": location, "num": num, "page": page, "type": type, "autocorrect": autocorrect, "time_range": time_range},
                         error_payload=_err("VALIDATION_ERROR", "gl must be a string.")["error"])
        return _err("VALIDATION_ERROR", "gl must be a string.")
    if hl is not None and not isinstance(hl, str):
        key_row, e = _auth_api_key(api_key)
        if key_row:
            _log_request(key_row["id"], {"api_key": api_key, "q": q, "gl": gl, "hl": hl, "location": location, "num": num, "page": page, "type": type, "autocorrect": autocorrect, "time_range": time_range},
                         error_payload=_err("VALIDATION_ERROR", "hl must be a string.")["error"])
        return _err("VALIDATION_ERROR", "hl must be a string.")
    if location is not None and not isinstance(location, str):
        key_row, e = _auth_api_key(api_key)
        if key_row:
            _log_request(key_row["id"], {"api_key": api_key, "q": q, "gl": gl, "hl": hl, "location": location, "num": num, "page": page, "type": type, "autocorrect": autocorrect, "time_range": time_range},
                         error_payload=_err("VALIDATION_ERROR", "location must be a string.")["error"])
        return _err("VALIDATION_ERROR", "location must be a string.")
    if num is not None:
        if not isinstance(num, int):
            key_row, _ = _auth_api_key(api_key)
            if key_row:
                _log_request(key_row["id"], {"api_key": api_key, "q": q, "gl": gl, "hl": hl, "location": location, "num": num, "page": page, "type": type, "autocorrect": autocorrect, "time_range": time_range},
                             error_payload=_err("VALIDATION_ERROR", "num must be an integer.")["error"])
            return _err("VALIDATION_ERROR", "num must be an integer.")
        if num < 1 or num > 100:
            key_row, _ = _auth_api_key(api_key)
            if key_row:
                _log_request(key_row["id"], {"api_key": api_key, "q": q, "gl": gl, "hl": hl, "location": location, "num": num, "page": page, "type": type, "autocorrect": autocorrect, "time_range": time_range},
                             error_payload=_err("VALIDATION_ERROR", "num must be between 1 and 100.")["error"])
            return _err("VALIDATION_ERROR", "num must be between 1 and 100.")
    if page is not None:
        if not isinstance(page, int):
            key_row, _ = _auth_api_key(api_key)
            if key_row:
                _log_request(key_row["id"], {"api_key": api_key, "q": q, "gl": gl, "hl": hl, "location": location, "num": num, "page": page, "type": type, "autocorrect": autocorrect, "time_range": time_range},
                             error_payload=_err("VALIDATION_ERROR", "page must be an integer.")["error"])
            return _err("VALIDATION_ERROR", "page must be an integer.")
        if page < 1:
            key_row, _ = _auth_api_key(api_key)
            if key_row:
                _log_request(key_row["id"], {"api_key": api_key, "q": q, "gl": gl, "hl": hl, "location": location, "num": num, "page": page, "type": type, "autocorrect": autocorrect, "time_range": time_range},
                             error_payload=_err("VALIDATION_ERROR", "page must be >= 1.")["error"])
            return _err("VALIDATION_ERROR", "page must be >= 1.")
    if type is not None:
        if not isinstance(type, str):
            key_row, _ = _auth_api_key(api_key)
            if key_row:
                _log_request(key_row["id"], {"api_key": api_key, "q": q, "gl": gl, "hl": hl, "location": location, "num": num, "page": page, "type": type, "autocorrect": autocorrect, "time_range": time_range},
                             error_payload=_err("VALIDATION_ERROR", "type must be a string.")["error"])
            return _err("VALIDATION_ERROR", "type must be a string.")
        if type not in ["search", "news", "images", "videos", "shopping"]:
            key_row, _ = _auth_api_key(api_key)
            if key_row:
                _log_request(key_row["id"], {"api_key": api_key, "q": q, "gl": gl, "hl": hl, "location": location, "num": num, "page": page, "type": type, "autocorrect": autocorrect, "time_range": time_range},
                             error_payload=_err("VALIDATION_ERROR", "Invalid type enum.")["error"])
            return _err("VALIDATION_ERROR", "Invalid type enum.")
    if autocorrect is not None and not isinstance(autocorrect, bool):
        key_row, _ = _auth_api_key(api_key)
        if key_row:
            _log_request(key_row["id"], {"api_key": api_key, "q": q, "gl": gl, "hl": hl, "location": location, "num": num, "page": page, "type": type, "autocorrect": autocorrect, "time_range": time_range},
                         error_payload=_err("VALIDATION_ERROR", "autocorrect must be a boolean.")["error"])
        return _err("VALIDATION_ERROR", "autocorrect must be a boolean.")
    if time_range is not None:
        if not isinstance(time_range, str):
            key_row, _ = _auth_api_key(api_key)
            if key_row:
                _log_request(key_row["id"], {"api_key": api_key, "q": q, "gl": gl, "hl": hl, "location": location, "num": num, "page": page, "type": type, "autocorrect": autocorrect, "time_range": time_range},
                             error_payload=_err("VALIDATION_ERROR", "time_range must be a string.")["error"])
            return _err("VALIDATION_ERROR", "time_range must be a string.")
        if time_range not in ["any", "h", "d", "w", "m", "y"]:
            key_row, _ = _auth_api_key(api_key)
            if key_row:
                _log_request(key_row["id"], {"api_key": api_key, "q": q, "gl": gl, "hl": hl, "location": location, "num": num, "page": page, "type": type, "autocorrect": autocorrect, "time_range": time_range},
                             error_payload=_err("VALIDATION_ERROR", "Invalid time_range enum.")["error"])
            return _err("VALIDATION_ERROR", "Invalid time_range enum.")

    # Authenticate
    key_row, auth_err = _auth_api_key(api_key)
    if auth_err:
        return auth_err
    api_keys = _load("api_keys.json")
    key_idx = next((i for i, k in enumerate(api_keys) if isinstance(k, dict) and k.get("id") == key_row.get("id")), None)
    if key_idx is None:
        return _err("UNAUTHORIZED", "api_key not found.")

    request_payload = {"api_key": api_key, "q": q, "gl": gl, "hl": hl, "location": location, "num": num, "page": page, "type": type, "autocorrect": autocorrect, "time_range": time_range}

    # Key status check
    if key_row.get("status") != "active":
        _log_request(key_row["id"], request_payload, error_payload=_err("UNAUTHORIZED", "API key is not active.", status=key_row.get("status"))["error"])
        return _err("UNAUTHORIZED", "API key is not active.", status=key_row.get("status"))

    # Normalize key usage_day rollover
    if key_row.get("usage_day") != usage_day:
        key_row["usage_day"] = usage_day
        key_row["usage_search_count"] = 0
        key_row["usage_scrape_count"] = 0
        key_row["updated_at"] = now_iso
        api_keys[key_idx] = key_row
        _save("api_keys.json", api_keys)

    # Rate limit enforcement: count requests in last 60s for this key across both tools
    logs = _load("request_logs.json")
    cutoff = now - datetime.timedelta(seconds=60)
    recent = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") != key_row["id"]:
            continue
        ts = _parse_rfc3339(r.get("created_at"))
        if ts and ts >= cutoff:
            recent += 1
    if isinstance(key_row.get("rate_limit_per_minute"), int) and recent >= key_row["rate_limit_per_minute"]:
        _log_request(key_row["id"], request_payload, error_payload=_err("RATE_LIMIT", "Rate limit exceeded.")["error"])
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    # Quota check (search per day)
    if not isinstance(key_row.get("quota_search_per_day"), int) or key_row["quota_search_per_day"] < 0:
        _log_request(key_row["id"], request_payload, error_payload=_err("VALIDATION_ERROR", "Key quota_search_per_day misconfigured.")["error"])
        return _err("VALIDATION_ERROR", "Key quota_search_per_day misconfigured.")
    if not isinstance(key_row.get("usage_search_count"), int) or key_row["usage_search_count"] < 0:
        key_row["usage_search_count"] = 0
    if key_row["usage_search_count"] >= key_row["quota_search_per_day"]:
        _log_request(key_row["id"], request_payload, error_payload=_err("QUOTA_EXCEEDED", "Daily search quota exceeded.")["error"])
        return _err("QUOTA_EXCEEDED", "Daily search quota exceeded.")

    # Build request_params object and size-check
    req_params = {k: v for k, v in {
        "q": q,
        "gl": gl,
        "hl": hl,
        "location": location,
        "num": num if num is not None else 10,
        "page": page if page is not None else 1,
        "type": type if type is not None else "search",
        "autocorrect": autocorrect if autocorrect is not None else True,
        "time_range": time_range if time_range is not None else "any",
    }.items() if v is not None}
    if not isinstance(req_params, dict) or not _json_obj_size_ok(req_params, 65536):
        _log_request(key_row["id"], request_payload, error_payload=_err("VALIDATION_ERROR", "request_params must be an object <= 64KB.")["error"])
        return _err("VALIDATION_ERROR", "request_params must be an object <= 64KB.")

    # Create search query job row (queued -> running -> succeeded)
    search_queries = _load("search_queries.json")
    search_results = _load("search_results.json")

    sq_id = _new_id("serper_q")
    sq_row = {
        "id": sq_id,
        "api_key_id": key_row["id"],
        "status": "queued",
        "request_params": req_params,
        "query_text": q.strip(),
        "provider": "serper",
        "provider_request_id": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "result_count": 0,
        "cost_units": 0,
        "started_at": None,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    search_queries.append(sq_row)
    _save("search_queries.json", search_queries)

    # Transition to running (and bill quota here, consistently)
    # lifecycle: queued -> running allowed
    sq_row["status"] = "running"
    sq_row["started_at"] = now_iso
    sq_row["updated_at"] = now_iso

    # Increment usage_search_count at running transition
    api_keys = _load("api_keys.json")
    key_idx = next((i for i, k in enumerate(api_keys) if isinstance(k, dict) and k.get("id") == key_row["id"]), None)
    if key_idx is None:
        # cannot proceed; mark failed and log
        sq_row["status"] = "failed"
        sq_row["error_code"] = "AUTH_LOST"
        sq_row["error_message"] = "API key record disappeared."
        sq_row["http_status"] = 401
        sq_row["finished_at"] = now_iso
        sq_row["updated_at"] = now_iso
        # persist update
        for i, r in enumerate(search_queries):
            if r.get("id") == sq_id:
                search_queries[i] = sq_row
                break
        _save("search_queries.json", search_queries)
        _log_request(key_row["id"], request_payload, error_payload=_err("UNAUTHORIZED", "API key not found.")["error"], search_query_id=sq_id)
        return _err("UNAUTHORIZED", "API key not found.")

    key_row = api_keys[key_idx]
    if key_row.get("usage_day") != usage_day:
        key_row["usage_day"] = usage_day
        key_row["usage_search_count"] = 0
        key_row["usage_scrape_count"] = 0

    if key_row.get("usage_search_count", 0) >= key_row.get("quota_search_per_day", 0):
        # quota exceeded at transition time; cancel job
        sq_row["status"] = "cancelled"
        sq_row["error_code"] = "QUOTA_EXCEEDED"
        sq_row["error_message"] = "Daily search quota exceeded."
        sq_row["http_status"] = 429
        sq_row["finished_at"] = now_iso
        sq_row["updated_at"] = now_iso
        for i, r in enumerate(search_queries):
            if r.get("id") == sq_id:
                search_queries[i] = sq_row
                break
        _save("search_queries.json", search_queries)
        _log_request(key_row["id"], request_payload, error_payload=_err("QUOTA_EXCEEDED", "Daily search quota exceeded.")["error"], search_query_id=sq_id)
        return _err("QUOTA_EXCEEDED", "Daily search quota exceeded.")

    key_row["usage_search_count"] = int(key_row.get("usage_search_count", 0)) + 1
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    api_keys[key_idx] = key_row
    _save("api_keys.json", api_keys)

    # Simulate provider results deterministically (offline) and store as artifacts
    vertical = req_params.get("type", "search")
    n = int(req_params.get("num", 10))
    p = int(req_params.get("page", 1))
    base_pos = (p - 1) * n
    allowed_types = {
        "search": "organic",
        "news": "news",
        "images": "image",
        "videos": "video",
        "shopping": "shopping",
    }
    result_type = allowed_types.get(vertical, "other")

    # create at least one result
    items = []
    for i in range(n):
        pos = base_pos + i + 1
        url = f"https://example.com/{vertical}/{hashlib.sha256((q+'|'+str(pos)).encode('utf-8')).hexdigest()[:16]}"
        title = f"{q.strip()} - {vertical} result {pos}"
        snippet = f"Simulated {vertical} snippet for '{q.strip()}', position {pos}."
        raw_item = {"title": title, "link": url, "snippet": snippet, "position": pos, "type": vertical, "gl": req_params.get("gl"), "hl": req_params.get("hl")}
        items.append((pos, raw_item, title, url, snippet))

    inserted = 0
    for pos, raw_item, title, url, snippet in items:
        # uniqueness (search_query_id, position, result_type)
        exists = False
        for r in search_results:
            if not isinstance(r, dict):
                continue
            if r.get("search_query_id") == sq_id and r.get("position") == pos and r.get("result_type") == result_type:
                exists = True
                break
        if exists:
            continue
        res_id = _new_id("serper_res")
        res_row = {
            "id": res_id,
            "search_query_id": sq_id,
            "position": pos,
            "result_type": result_type,
            "title": title,
            "url": url,
            "display_url": url.replace("https://", ""),
            "snippet": snippet,
            "source": None,
            "published_at": None,
            "raw_item": raw_item if isinstance(raw_item, dict) else {},
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        search_results.append(res_row)
        inserted += 1

    if inserted <= 0:
        # should never happen; fail job
        sq_row["status"] = "failed"
        sq_row["error_code"] = "NO_RESULTS"
        sq_row["error_message"] = "No results could be stored."
        sq_row["http_status"] = 502
        sq_row["finished_at"] = now_iso
        sq_row["updated_at"] = now_iso
        for i, r in enumerate(search_queries):
            if r.get("id") == sq_id:
                search_queries[i] = sq_row
                break
        _save("search_queries.json", search_queries)
        _save("search_results.json", search_results)
        _log_request(key_row["id"], request_payload, error_payload=_err("CONFLICT", "No results stored.")["error"], search_query_id=sq_id)
        return _err("CONFLICT", "No results stored.")

    _save("search_results.json", search_results)

    # Transition to succeeded
    sq_row["status"] = "succeeded"
    sq_row["http_status"] = 200
    sq_row["provider_request_id"] = _new_id("serper_req")
    sq_row["result_count"] = inserted
    sq_row["cost_units"] = 1
    sq_row["finished_at"] = now_iso
    sq_row["updated_at"] = now_iso

    # persist updated search query row
    for i, r in enumerate(search_queries):
        if isinstance(r, dict) and r.get("id") == sq_id:
            search_queries[i] = sq_row
            break
    _save("search_queries.json", search_queries)

    # Gather results to return for requested page slice: positions base_pos+1..base_pos+n of this query
    results_out = []
    for r in search_results:
        if not isinstance(r, dict):
            continue
        if r.get("search_query_id") != sq_id:
            continue
        if r.get("result_type") != result_type:
            continue
        pos = r.get("position")
        if isinstance(pos, int) and (base_pos + 1) <= pos <= (base_pos + n):
            results_out.append(r)

    results_out.sort(key=lambda x: x.get("position", 10**9))

    response = {
        "search_query": sq_row,
        "results": results_out,
        "meta": {
            "page": p,
            "num": n,
            "type": vertical,
            "returned": len(results_out),
            "total_stored_for_query": sq_row["result_count"],
        },
    }

    _log_request(key_row["id"], request_payload, response_payload=response, search_query_id=sq_id)
    return response

def scrape(api_key, url, search_result_id=None, extract=None, render=None, timeout_ms=None, **_extra):
    import json, os, datetime, time, re, uuid, base64
    from urllib.parse import urlparse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0418000" if __import__("os").path.isdir("./environment_mix/0418000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"
    usage_day = now.date().isoformat()

    def _ms():
        return int((time.time() - t0) * 1000)

    def _new_id(prefix):
        token = base64.b32encode(uuid.uuid4().bytes).decode("ascii").rstrip("=")
        return f"{prefix}_{token}"

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    def _json_obj_size_ok(obj, limit_bytes=65536):
        try:
            b = json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
            return len(b) <= limit_bytes
        except Exception:
            return False

    def _auth_api_key(raw):
        if not isinstance(raw, str) or not raw.strip():
            return None, _err("UNAUTHORIZED", "Missing or invalid api_key.")
        raw = raw.strip()
        keys = _load("api_keys.json")
        candidates = []
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("id") == raw:
                candidates.append(k)
            elif isinstance(k.get("key_prefix"), str) and raw.startswith(k["key_prefix"]):
                candidates.append(k)
        if not candidates:
            return None, _err("UNAUTHORIZED", "api_key not found.")
        chosen = None
        for k in candidates:
            if k.get("status") == "active":
                chosen = k
                break
        if chosen is None:
            chosen = candidates[0]
        return chosen, None

    def _log_request(api_key_id, request_payload, response_payload=None, error_payload=None, scrape_job_id=None):
        logs = _load("request_logs.json")
        entry = {
            "id": _new_id("reqlog"),
            "api_key_id": api_key_id,
            "tool_name": "scrape",
            "search_query_id": None,
            "scrape_job_id": scrape_job_id,
            "request_payload": request_payload if isinstance(request_payload, dict) else {},
            "response_payload": response_payload,
            "error_payload": error_payload,
            "latency_ms": max(0, _ms()),
            "client_ip": None,
            "user_agent": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        logs.append(entry)
        _save("request_logs.json", logs)
        return entry

    # Validate inputs
    if not isinstance(api_key, str):
        return _err("VALIDATION_ERROR", "api_key must be a string.")
    if not isinstance(url, str) or not url.strip():
        key_row, _ = _auth_api_key(api_key)
        if key_row:
            _log_request(key_row["id"], {"api_key": api_key, "url": url, "search_result_id": search_result_id, "extract": extract, "render": render, "timeout_ms": timeout_ms},
                         error_payload=_err("VALIDATION_ERROR", "url must be a non-empty string.")["error"])
        return _err("VALIDATION_ERROR", "url must be a non-empty string.")

    if search_result_id is not None:
        if not isinstance(search_result_id, str) or not re.match(r"^serper_res_[0-9A-Z]{10,}$", search_result_id):
            key_row, _ = _auth_api_key(api_key)
            if key_row:
                _log_request(key_row["id"], {"api_key": api_key, "url": url, "search_result_id": search_result_id, "extract": extract, "render": render, "timeout_ms": timeout_ms},
                             error_payload=_err("VALIDATION_ERROR", "search_result_id is invalid.")["error"])
            return _err("VALIDATION_ERROR", "search_result_id is invalid.")
    if extract is not None:
        if not isinstance(extract, str) or extract not in ["text", "html", "both"]:
            key_row, _ = _auth_api_key(api_key)
            if key_row:
                _log_request(key_row["id"], {"api_key": api_key, "url": url, "search_result_id": search_result_id, "extract": extract, "render": render, "timeout_ms": timeout_ms},
                             error_payload=_err("VALIDATION_ERROR", "extract must be one of: text, html, both.")["error"])
            return _err("VALIDATION_ERROR", "extract must be one of: text, html, both.")
    if render is not None and not isinstance(render, bool):
        key_row, _ = _auth_api_key(api_key)
        if key_row:
            _log_request(key_row["id"], {"api_key": api_key, "url": url, "search_result_id": search_result_id, "extract": extract, "render": render, "timeout_ms": timeout_ms},
                         error_payload=_err("VALIDATION_ERROR", "render must be a boolean.")["error"])
        return _err("VALIDATION_ERROR", "render must be a boolean.")
    if timeout_ms is not None:
        if not isinstance(timeout_ms, int) or timeout_ms < 1000 or timeout_ms > 120000:
            key_row, _ = _auth_api_key(api_key)
            if key_row:
                _log_request(key_row["id"], {"api_key": api_key, "url": url, "search_result_id": search_result_id, "extract": extract, "render": render, "timeout_ms": timeout_ms},
                             error_payload=_err("VALIDATION_ERROR", "timeout_ms must be between 1000 and 120000.")["error"])
            return _err("VALIDATION_ERROR", "timeout_ms must be between 1000 and 120000.")

    # URL format validation
    parsed = urlparse(url.strip())
    if parsed.scheme not in ("http", "https") or not parsed.netloc:
        key_row, _ = _auth_api_key(api_key)
        if key_row:
            _log_request(key_row["id"], {"api_key": api_key, "url": url, "search_result_id": search_result_id, "extract": extract, "render": render, "timeout_ms": timeout_ms},
                         error_payload=_err("VALIDATION_ERROR", "url must be a fully-qualified http(s) URL.")["error"])
        return _err("VALIDATION_ERROR", "url must be a fully-qualified http(s) URL.")

    # Authenticate
    key_row, auth_err = _auth_api_key(api_key)
    if auth_err:
        return auth_err
    api_keys = _load("api_keys.json")
    key_idx = next((i for i, k in enumerate(api_keys) if isinstance(k, dict) and k.get("id") == key_row.get("id")), None)
    if key_idx is None:
        return _err("UNAUTHORIZED", "api_key not found.")

    request_payload = {"api_key": api_key, "url": url, "search_result_id": search_result_id, "extract": extract, "render": render, "timeout_ms": timeout_ms}

    if key_row.get("status") != "active":
        _log_request(key_row["id"], request_payload, error_payload=_err("UNAUTHORIZED", "API key is not active.", status=key_row.get("status"))["error"])
        return _err("UNAUTHORIZED", "API key is not active.", status=key_row.get("status"))

    # Normalize key usage_day rollover
    if key_row.get("usage_day") != usage_day:
        key_row["usage_day"] = usage_day
        key_row["usage_search_count"] = 0
        key_row["usage_scrape_count"] = 0
        key_row["updated_at"] = now_iso
        api_keys[key_idx] = key_row
        _save("api_keys.json", api_keys)

    # Rate limit enforcement
    logs = _load("request_logs.json")
    cutoff = now - datetime.timedelta(seconds=60)
    recent = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") != key_row["id"]:
            continue
        ts = _parse_rfc3339(r.get("created_at"))
        if ts and ts >= cutoff:
            recent += 1
    if isinstance(key_row.get("rate_limit_per_minute"), int) and recent >= key_row["rate_limit_per_minute"]:
        _log_request(key_row["id"], request_payload, error_payload=_err("RATE_LIMIT", "Rate limit exceeded.")["error"])
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    # Quota check (scrape per day)
    if not isinstance(key_row.get("quota_scrape_per_day"), int) or key_row["quota_scrape_per_day"] < 0:
        _log_request(key_row["id"], request_payload, error_payload=_err("VALIDATION_ERROR", "Key quota_scrape_per_day misconfigured.")["error"])
        return _err("VALIDATION_ERROR", "Key quota_scrape_per_day misconfigured.")
    if not isinstance(key_row.get("usage_scrape_count"), int) or key_row["usage_scrape_count"] < 0:
        key_row["usage_scrape_count"] = 0
    if key_row["usage_scrape_count"] >= key_row["quota_scrape_per_day"]:
        _log_request(key_row["id"], request_payload, error_payload=_err("QUOTA_EXCEEDED", "Daily scrape quota exceeded.")["error"])
        return _err("QUOTA_EXCEEDED", "Daily scrape quota exceeded.")

    # Resolve optional linked search result and enforce URL consistency rule
    linked_res = None
    if search_result_id is not None:
        all_results = _load("search_results.json")
        for r in all_results:
            if isinstance(r, dict) and r.get("id") == search_result_id:
                linked_res = r
                break
        if linked_res is None:
            _log_request(key_row["id"], request_payload, error_payload=_err("NOT_FOUND", "Linked search result not found.")["error"])
            return _err("NOT_FOUND", "Linked search result not found.")
        res_url = linked_res.get("url")
        if res_url is not None and url.strip() != res_url:
            _log_request(key_row["id"], request_payload, error_payload=_err("CONFLICT", "url must match linked search result url.", expected_url=res_url)["error"])
            return _err("CONFLICT", "url must match linked search result url.", expected_url=res_url)

    # Build request_params and size-check
    req_params = {
        "url": url.strip(),
        "extract": extract if extract is not None else "text",
        "render": render if render is not None else False,
        "timeout_ms": timeout_ms if timeout_ms is not None else 30000,
        "search_result_id": search_result_id,
    }
    if not isinstance(req_params, dict) or not _json_obj_size_ok(req_params, 65536):
        _log_request(key_row["id"], request_payload, error_payload=_err("VALIDATION_ERROR", "request_params must be an object <= 64KB.")["error"])
        return _err("VALIDATION_ERROR", "request_params must be an object <= 64KB.")

    # Create scrape job row (queued -> running -> succeeded)
    scrape_jobs = _load("scrape_jobs.json")
    job_id = _new_id("scrape")
    job = {
        "id": job_id,
        "api_key_id": key_row["id"],
        "status": "queued",
        "request_params": req_params,
        "url": url.strip(),
        "linked_search_result_id": search_result_id,
        "http_status": None,
        "content_type": None,
        "content_bytes": 0,
        "extracted_text": None,
        "extracted_html": None,
        "raw_response": None,
        "error_code": None,
        "error_message": None,
        "cost_units": 0,
        "started_at": None,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    scrape_jobs.append(job)
    _save("scrape_jobs.json", scrape_jobs)

    # Transition to running (and bill here)
    job["status"] = "running"
    job["started_at"] = now_iso
    job["updated_at"] = now_iso

    api_keys = _load("api_keys.json")
    key_idx = next((i for i, k in enumerate(api_keys) if isinstance(k, dict) and k.get("id") == key_row["id"]), None)
    if key_idx is None:
        job["status"] = "failed"
        job["error_code"] = "AUTH_LOST"
        job["error_message"] = "API key record disappeared."
        job["http_status"] = 401
        job["finished_at"] = now_iso
        job["updated_at"] = now_iso
        for i, r in enumerate(scrape_jobs):
            if isinstance(r, dict) and r.get("id") == job_id:
                scrape_jobs[i] = job
                break
        _save("scrape_jobs.json", scrape_jobs)
        _log_request(key_row["id"], request_payload, error_payload=_err("UNAUTHORIZED", "API key not found.")["error"], scrape_job_id=job_id)
        return _err("UNAUTHORIZED", "API key not found.")

    key_row = api_keys[key_idx]
    if key_row.get("usage_day") != usage_day:
        key_row["usage_day"] = usage_day
        key_row["usage_search_count"] = 0
        key_row["usage_scrape_count"] = 0

    if key_row.get("usage_scrape_count", 0) >= key_row.get("quota_scrape_per_day", 0):
        job["status"] = "cancelled"
        job["error_code"] = "QUOTA_EXCEEDED"
        job["error_message"] = "Daily scrape quota exceeded."
        job["http_status"] = 429
        job["finished_at"] = now_iso
        job["updated_at"] = now_iso
        for i, r in enumerate(scrape_jobs):
            if isinstance(r, dict) and r.get("id") == job_id:
                scrape_jobs[i] = job
                break
        _save("scrape_jobs.json", scrape_jobs)
        _log_request(key_row["id"], request_payload, error_payload=_err("QUOTA_EXCEEDED", "Daily scrape quota exceeded.")["error"], scrape_job_id=job_id)
        return _err("QUOTA_EXCEEDED", "Daily scrape quota exceeded.")

    key_row["usage_scrape_count"] = int(key_row.get("usage_scrape_count", 0)) + 1
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    api_keys[key_idx] = key_row
    _save("api_keys.json", api_keys)

    # Simulate extraction; enforce 2MB limits with truncation note
    MAX_ARTIFACT = 2 * 1024 * 1024
    mode = req_params.get("extract", "text")
    want_text = mode in ("text", "both")
    want_html = mode in ("html", "both")

    extracted_text = None
    extracted_html = None
    trunc_info = {}

    if want_text:
        extracted_text = f"Simulated extracted text for {url.strip()} (render={bool(req_params.get('render'))})."
        b = extracted_text.encode("utf-8")
        if len(b) > MAX_ARTIFACT:
            extracted_text = b[:MAX_ARTIFACT].decode("utf-8", errors="ignore")
            trunc_info["text_truncated"] = True
            trunc_info["text_original_bytes"] = len(b)

    if want_html:
        extracted_html = f"<html><head><title>Simulated</title></head><body><p>Simulated HTML for {url.strip()}</p></body></html>"
        b = extracted_html.encode("utf-8")
        if len(b) > MAX_ARTIFACT:
            extracted_html = b[:MAX_ARTIFACT].decode("utf-8", errors="ignore")
            trunc_info["html_truncated"] = True
            trunc_info["html_original_bytes"] = len(b)

    # Ensure success rule: succeeded must have at least one artifact/raw_response
    if extracted_text is None and extracted_html is None:
        job["status"] = "failed"
        job["http_status"] = 502
        job["error_code"] = "NO_EXTRACTION"
        job["error_message"] = "No extraction mode produced content."
        job["content_bytes"] = 0
        job["cost_units"] = 1
        job["finished_at"] = now_iso
        job["updated_at"] = now_iso
    else:
        job["status"] = "succeeded"
        job["http_status"] = 200
        job["content_type"] = "text/html" if extracted_html is not None else "text/plain"
        job["extracted_text"] = extracted_text
        job["extracted_html"] = extracted_html
        content_bytes = 0
        if extracted_text is not None:
            content_bytes += len(extracted_text.encode("utf-8"))
        if extracted_html is not None:
            content_bytes += len(extracted_html.encode("utf-8"))
        job["content_bytes"] = content_bytes
        job["raw_response"] = {"provider": "serper", "render": bool(req_params.get("render")), **trunc_info} if trunc_info else {"provider": "serper", "render": bool(req_params.get("render"))}
        job["cost_units"] = 1
        job["finished_at"] = now_iso
        job["updated_at"] = now_iso

    # Persist job update
    for i, r in enumerate(scrape_jobs):
        if isinstance(r, dict) and r.get("id") == job_id:
            scrape_jobs[i] = job
            break
    _save("scrape_jobs.json", scrape_jobs)

    response = {"scrape_job": job}
    if job["status"] == "succeeded":
        _log_request(key_row["id"], request_payload, response_payload=response, scrape_job_id=job_id)
        return response
    else:
        err = _err("CONFLICT", "Scrape failed.", error_code=job.get("error_code"), error_message=job.get("error_message"))
        _log_request(key_row["id"], request_payload, error_payload=err["error"], scrape_job_id=job_id)
        return err

def whoami(api_key, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0418000" if __import__("os").path.isdir("./environment_mix/0418000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"
    usage_day = now.date().isoformat()

    def _ms():
        return int((time.time() - t0) * 1000)

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    def _new_id(prefix="reqlog"):
        import uuid, base64
        token = base64.b32encode(uuid.uuid4().bytes).decode("ascii").rstrip("=")
        return f"{prefix}_{token}"

    def _log_request(api_key_id, request_payload, response_payload=None, error_payload=None):
        logs = _load("request_logs.json")
        entry = {
            "id": _new_id("reqlog"),
            "api_key_id": api_key_id,
            "tool_name": "google_search",  # whoami not in enum; log under closest supported? Avoid violating enum by not logging if impossible.
            "search_query_id": None,
            "scrape_job_id": None,
            "request_payload": request_payload if isinstance(request_payload, dict) else {},
            "response_payload": response_payload,
            "error_payload": error_payload,
            "latency_ms": max(0, _ms()),
            "client_ip": None,
            "user_agent": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        logs.append(entry)
        _save("request_logs.json", logs)
        return entry

    # Validate
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("UNAUTHORIZED", "Missing or invalid api_key.")

    # Authenticate by id or prefix
    keys = _load("api_keys.json")
    raw = api_key.strip()
    candidates = []
    for k in keys:
        if not isinstance(k, dict):
            continue
        if k.get("id") == raw:
            candidates.append(k)
        elif isinstance(k.get("key_prefix"), str) and raw.startswith(k["key_prefix"]):
            candidates.append(k)

    if not candidates:
        return _err("UNAUTHORIZED", "api_key not found.")

    key_row = None
    for k in candidates:
        if k.get("status") == "active":
            key_row = k
            break
    if key_row is None:
        key_row = candidates[0]

    if key_row.get("status") != "active":
        # do not create jobs; may log error, but request_logs.tool_name enum doesn't include whoami.
        return _err("UNAUTHORIZED", "API key is not active.", status=key_row.get("status"))

    # Compute rate usage for last 60 seconds
    logs = _load("request_logs.json")
    cutoff = now - datetime.timedelta(seconds=60)
    recent = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") != key_row.get("id"):
            continue
        ts = _parse_rfc3339(r.get("created_at"))
        if ts and ts >= cutoff:
            recent += 1

    # Usage day normalization preview
    usage_search = key_row.get("usage_search_count", 0) if key_row.get("usage_day") == usage_day else 0
    usage_scrape = key_row.get("usage_scrape_count", 0) if key_row.get("usage_day") == usage_day else 0

    safe_key = {k: key_row.get(k) for k in [
        "id", "key_prefix", "label", "status", "plan",
        "quota_search_per_day", "quota_scrape_per_day", "rate_limit_per_minute",
        "usage_day", "usage_search_count", "usage_scrape_count",
        "last_used_at", "created_at", "updated_at"
    ]}

    response = {
        "api_key": safe_key,
        "consumption": {
            "utc_day": usage_day,
            "usage_day_recorded": key_row.get("usage_day"),
            "search_used_today": int(usage_search) if isinstance(usage_search, int) else 0,
            "search_quota_per_day": key_row.get("quota_search_per_day"),
            "scrape_used_today": int(usage_scrape) if isinstance(usage_scrape, int) else 0,
            "scrape_quota_per_day": key_row.get("quota_scrape_per_day"),
            "requests_last_60s": recent,
            "rate_limit_per_minute": key_row.get("rate_limit_per_minute"),
        }
    }
    # Cannot log without violating tool_name enum; return response.
    return response

