            if key_row:
                _log_request(key_row["id"], {"api_key": api_key, "status": status, "provider": provider, "created_from": created_from, "created_to": created_to, "limit": limit, "cursor": cursor},
                             error_payload=_err("VALIDATION_ERROR", "Invalid provider filter.")["error"])
            return _err("VALIDATION_ERROR", "Invalid provider filter.")
    dt_from = None
    dt_to = None
    if created_from is not None:
        dt_from = _parse_rfc3339(created_from)
        if dt_from is None:
            key_row, _ = _auth_api_key(api_key)
            if key_row:
                _log_request(key_row["id"], {"api_key": api_key, "status": status, "provider": provider, "created_from": created_from, "created_to": created_to, "limit": limit, "cursor": cursor},
                             error_payload=_err("VALIDATION_ERROR", "created_from must be RFC3339 date-time.")["error"])
            return _err("VALIDATION_ERROR", "created_from must be RFC3339 date-time.")
    if created_to is not None:
        dt_to = _parse_rfc3339(created_to)
        if dt_to is None:
            key_row, _ = _auth_api_key(api_key)
            if key_row:
                _log_request(key_row["id"], {"api_key": api_key, "status": status, "provider": provider, "created_from": created_from, "created_to": created_to, "limit": limit, "cursor": cursor},
                             error_payload=_err("VALIDATION_ERROR", "created_to must be RFC3339 date-time.")["error"])
            return _err("VALIDATION_ERROR", "created_to must be RFC3339 date-time.")
    if limit is not None:
        if not isinstance(limit, int) or limit < 1 or limit > 100:
            key_row, _ = _auth_api_key(api_key)
            if key_row:
                _log_request(key_row["id"], {"api_key": api_key, "status": status, "provider": provider, "created_from": created_from, "created_to": created_to, "limit": limit, "cursor": cursor},
                             error_payload=_err("VALIDATION_ERROR", "limit must be between 1 and 100.")["error"])
            return _err("VALIDATION_ERROR", "limit must be between 1 and 100.")
    page_limit = limit if limit is not None else 20

    # Decode cursor (opaque): base64 json {"created_at": "...", "id":"..."}
    cursor_created = None
    cursor_id = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            key_row, _ = _auth_api_key(api_key)
            if key_row:
                _log_request(key_row["id"], {"api_key": api_key, "status": status, "provider": provider, "created_from": created_from, "created_to": created_to, "limit": limit, "cursor": cursor},
                             error_payload=_err("VALIDATION_ERROR", "cursor must be a string.")["error"])
            return _err("VALIDATION_ERROR", "cursor must be a string.")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
        except Exception:
            key_row, _ = _auth_api_key(api_key)
            if key_row:
                _log_request(key_row["id"], {"api_key": api_key, "status": status, "provider": provider, "created_from": created_from, "created_to": created_to, "limit": limit, "cursor": cursor},
                             error_payload=_err("VALIDATION_ERROR", "Invalid cursor.")["error"])
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        if not isinstance(obj, dict):
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        cursor_created = _parse_rfc3339(obj.get("created_at"))
        cursor_id = obj.get("id")
        if cursor_created is None or not isinstance(cursor_id, str):
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    # Authenticate
    key_row, auth_err = _auth_api_key(api_key)
    if auth_err:
        return auth_err

    if key_row.get("status") != "active":
        _log_request(key_row["id"], {"api_key": api_key, "status": status, "provider": provider, "created_from": created_from, "created_to": created_to, "limit": limit, "cursor": cursor},
                     error_payload=_err("UNAUTHORIZED", "API key is not active.", status=key_row.get("status"))["error"])
        return _err("UNAUTHORIZED", "API key is not active.", status=key_row.get("status"))

    # Rate limit enforcement (combined)
    logs = _load("request_logs.json")
    cutoff = now - datetime.timedelta(seconds=60)
    recent = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") != key_row["id"]:
            continue
        ts = _parse_rfc3339(r.get("created_at"))
        if ts and ts >= cutoff:
            recent += 1
    if isinstance(key_row.get("rate_limit_per_minute"), int) and recent >= key_row["rate_limit_per_minute"]:
        _log_request(key_row["id"], {"api_key": api_key, "status": status, "provider": provider, "created_from": created_from, "created_to": created_to, "limit": limit, "cursor": cursor},
                     error_payload=_err("RATE_LIMIT", "Rate limit exceeded.")["error"])
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    # Query
    sqs = _load("search_queries.json")
    scoped = []
    for r in sqs:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") != key_row["id"]:
            continue
        if status is not None and r.get("status") != status:
            continue
        if provider is not None and r.get("provider") != provider:
            continue
        created = _parse_rfc3339(r.get("created_at"))
        if dt_from and (created is None or created < dt_from):
            continue
        if dt_to and (created is None or created > dt_to):
            continue
        # cursor: newest-first pagination; include only rows strictly older than cursor tuple
        if cursor_created is not None:
            if created is None:
                continue
            if created > cursor_created:
                continue
            if created == cursor_created and isinstance(r.get("id"), str) and r["id"] >= cursor_id:
                continue
        scoped.append(r)

    # Sort newest-first by created_at then id desc
    def _sort_key(x):
        dt = _parse_rfc3339(x.get("created_at")) or datetime.datetime(1970, 1, 1)
        return (dt, x.get("id") or "")
    scoped.sort(key=_sort_key, reverse=True)

    total = len(scoped)
    page_items = scoped[:page_limit]
    has_more = total > page_limit

    next_cursor = None
    if has_more and page_items:
        last = page_items[-1]
        payload = {"created_at": last.get("created_at"), "id": last.get("id")}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    response = {
        "data": page_items,
        "meta": {
            "total": total,
            "limit": page_limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
        }
    }
    _log_request(key_row["id"], {"api_key": api_key, "status": status, "provider": provider, "created_from": created_from, "created_to": created_to, "limit": limit, "cursor": cursor},
                 response_payload=response)
    return response

def get_search_query(api_key, search_query_id, include_results=None, results_limit=None, results_cursor=None, **_extra):
    import json, os, datetime, time, secrets, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0418000" if __import__("os").path.isdir("./environment_mix/0418000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_utc = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now_utc.isoformat().replace("+00:00", "Z")

    def _lat_ms():
        return max(0, int((time.time() - t0) * 1000))

    def _new_id(prefix):
        alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567"
        return prefix + "".join(secrets.choice(alphabet) for _ in range(20))

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _minute_bucket(dt):
        # dt must be aware UTC
        return dt.replace(second=0, microsecond=0)

    def _rate_limited(log_rows, api_key_id, rate_limit_per_minute):
        if not isinstance(rate_limit_per_minute, int) or rate_limit_per_minute < 1:
            rate_limit_per_minute = 60
        bucket = _minute_bucket(now_utc)
        cnt = 0
        for r in log_rows:
            if r.get("api_key_id") != api_key_id:
                continue
            ts = _parse_dt(r.get("created_at"))
            if ts is None:
                continue
            if _minute_bucket(ts) == bucket:
                cnt += 1
        return cnt >= rate_limit_per_minute

    def _append_log(logs, api_key_id, tool_name, request_payload, response_payload=None, error_payload=None, search_query_id=None, scrape_job_id=None):
        log = {
            "id": _new_id("serper_log_"),
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "search_query_id": search_query_id,
            "scrape_job_id": scrape_job_id,
            "request_payload": request_payload if isinstance(request_payload, dict) else {},
            "response_payload": response_payload,
            "error_payload": error_payload,
            "latency_ms": _lat_ms(),
            "client_ip": None,
            "user_agent": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        logs.append(log)
        return log

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        # Cannot log without api_key_id
        return _err("UNAUTHORIZED", "Missing or invalid api_key.")
    if not isinstance(search_query_id, str) or not re.match(r"^serper_srch_[0-9A-Z]{10,}$", search_query_id):
        return _err("VALIDATION_ERROR", "Invalid search_query_id.", field="search_query_id")
    if include_results is None:
        include_results = False
    if not isinstance(include_results, bool):
        return _err("VALIDATION_ERROR", "include_results must be a boolean.", field="include_results")
    if results_limit is None:
        results_limit = 10
    if not isinstance(results_limit, int) or results_limit < 1 or results_limit > 100:
        return _err("VALIDATION_ERROR", "results_limit must be an integer between 1 and 100.", field="results_limit")
    if results_cursor is not None and (not isinstance(results_cursor, str) or len(results_cursor) > 200):
        return _err("VALIDATION_ERROR", "results_cursor must be a string.", field="results_cursor")

    # Load datastore
    keys = _load("api_keys.json")
    queries = _load("search_queries.json")
    results = _load("search_results.json")
    logs = _load("request_logs.json")

    # Authenticate: accept id or key_prefix (never key_hash)
    provided = api_key.strip()
    key_row = None
    for k in keys:
        if k.get("id") == provided or k.get("key_prefix") == provided:
            key_row = k
            break
    if key_row is None:
        return _err("UNAUTHORIZED", "Invalid api_key.")

    api_key_id = key_row.get("id")

    # Rate limit (logged on violation)
    if _rate_limited(logs, api_key_id, key_row.get("rate_limit_per_minute")):
        err = _err("RATE_LIMIT", "Rate limit exceeded.")
        _append_log(
            logs,
            api_key_id=api_key_id,
            tool_name="google_search",
            request_payload={
                "api_key": "***",
                "search_query_id": search_query_id,
                "include_results": include_results,
                "results_limit": results_limit,
                "results_cursor": results_cursor,
            },
            error_payload=err,
            search_query_id=None,
        )
        _save("request_logs.json", logs)
        return err

    # Forbidden/disabled key: reject and may log error
    if key_row.get("status") != "active":
        err = _err("UNAUTHORIZED", "API key is not active.", status=key_row.get("status"))
        _append_log(
            logs,
            api_key_id=api_key_id,
            tool_name="google_search",
            request_payload={
                "api_key": "***",
                "search_query_id": search_query_id,
                "include_results": include_results,
                "results_limit": results_limit,
                "results_cursor": results_cursor,
            },
            error_payload=err,
            search_query_id=None,
        )
        _save("request_logs.json", logs)
        return err

    # Find query; enforce ownership by api_key_id
    qry = None
    for q in queries:
        if q.get("id") == search_query_id and q.get("api_key_id") == api_key_id:
            qry = q
            break
    if qry is None:
        err = _err("NOT_FOUND", "Search query not found.")
        _append_log(
            logs,
            api_key_id=api_key_id,
            tool_name="google_search",
            request_payload={
                "api_key": "***",
                "search_query_id": search_query_id,
                "include_results": include_results,
                "results_limit": results_limit,
                "results_cursor": results_cursor,
            },
            error_payload=err,
            search_query_id=None,
        )
        _save("request_logs.json", logs)
        return err

    # Build response
    job = dict(qry)

    out = {"search_query": job}

    if include_results:
        # Pagination: cursor is integer offset encoded as "offset:<n>"
        offset = 0
        if results_cursor:
            m = re.match(r"^offset:(\d+)$", results_cursor)
            if not m:
                err = _err("VALIDATION_ERROR", "Invalid results_cursor.", field="results_cursor")
                _append_log(
                    logs,
                    api_key_id=api_key_id,
                    tool_name="google_search",
                    request_payload={
                        "api_key": "***",
                        "search_query_id": search_query_id,
                        "include_results": include_results,
                        "results_limit": results_limit,
                        "results_cursor": results_cursor,
                    },
                    error_payload=err,
                    search_query_id=search_query_id,
                )
                _save("request_logs.json", logs)
                return err
            offset = int(m.group(1))

        owned = [r for r in results if r.get("search_query_id") == search_query_id]
        # stable ordering: result_type then position then id
        owned.sort(key=lambda x: (str(x.get("result_type") or ""), int(x.get("position") or 10**9), str(x.get("id") or "")))

        total = len(owned)
        page = owned[offset:offset + results_limit]
        next_off = offset + len(page)
        has_more = next_off < total
        next_cursor = f"offset:{next_off}" if has_more else None

        out["results"] = page
        out["results_page"] = {"total": total, "has_more": has_more, "next_cursor": next_cursor, "limit": results_limit}

    # Update key last_used_at on successful authenticated request (read counts for RL via logs, not this)
    # Also write request log (required observable dynamics)
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    _save("api_keys.json", keys)

    _append_log(
        logs,
        api_key_id=api_key_id,
        tool_name="google_search",
        request_payload={
            "api_key": "***",
            "search_query_id": search_query_id,
            "include_results": include_results,
            "results_limit": results_limit,
            "results_cursor": results_cursor,
        },
        response_payload=out,
        error_payload=None,
        search_query_id=search_query_id,
    )
    _save("request_logs.json", logs)
    return out

def cancel_search_query(api_key, search_query_id, reason=None, **_extra):
    import json, os, datetime, time, secrets, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0418000" if __import__("os").path.isdir("./environment_mix/0418000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_utc = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now_utc.isoformat().replace("+00:00", "Z")

    def _lat_ms():
        return max(0, int((time.time() - t0) * 1000))

    def _new_id(prefix):
        alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567"
        return prefix + "".join(secrets.choice(alphabet) for _ in range(20))

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _minute_bucket(dt):
        return dt.replace(second=0, microsecond=0)

    def _rate_limited(log_rows, api_key_id, rate_limit_per_minute):
        if not isinstance(rate_limit_per_minute, int) or rate_limit_per_minute < 1:
            rate_limit_per_minute = 60
        bucket = _minute_bucket(now_utc)
        cnt = 0
        for r in log_rows:
            if r.get("api_key_id") != api_key_id:
                continue
            ts = _parse_dt(r.get("created_at"))
            if ts is None:
                continue
            if _minute_bucket(ts) == bucket:
                cnt += 1
        return cnt >= rate_limit_per_minute

    def _append_log(logs, api_key_id, tool_name, request_payload, response_payload=None, error_payload=None, search_query_id=None, scrape_job_id=None):
        log = {
            "id": _new_id("serper_log_"),
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "search_query_id": search_query_id,
            "scrape_job_id": scrape_job_id,
            "request_payload": request_payload if isinstance(request_payload, dict) else {},
            "response_payload": response_payload,
            "error_payload": error_payload,
            "latency_ms": _lat_ms(),
            "client_ip": None,
            "user_agent": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        logs.append(log)
        return log

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("UNAUTHORIZED", "Missing or invalid api_key.")
    if not isinstance(search_query_id, str) or not re.match(r"^serper_srch_[0-9A-Z]{10,}$", search_query_id):
        return _err("VALIDATION_ERROR", "Invalid search_query_id.", field="search_query_id")
    if reason is not None:
        if not isinstance(reason, str):
            return _err("VALIDATION_ERROR", "reason must be a string.", field="reason")
        if len(reason) > 500:
            return _err("VALIDATION_ERROR", "reason exceeds maxLength 500.", field="reason")

    keys = _load("api_keys.json")
    queries = _load("search_queries.json")
    logs = _load("request_logs.json")

    provided = api_key.strip()
    key_row = None
    for k in keys:
        if k.get("id") == provided or k.get("key_prefix") == provided:
            key_row = k
            break
    if key_row is None:
        return _err("UNAUTHORIZED", "Invalid api_key.")
    api_key_id = key_row.get("id")

    if _rate_limited(logs, api_key_id, key_row.get("rate_limit_per_minute")):
        err = _err("RATE_LIMIT", "Rate limit exceeded.")
        _append_log(
            logs,
            api_key_id=api_key_id,
            tool_name="google_search",
            request_payload={"api_key": "***", "search_query_id": search_query_id, "reason": reason},
            error_payload=err,
        )
        _save("request_logs.json", logs)
        return err

    if key_row.get("status") != "active":
        err = _err("UNAUTHORIZED", "API key is not active.", status=key_row.get("status"))
        _append_log(
            logs,
            api_key_id=api_key_id,
            tool_name="google_search",
            request_payload={"api_key": "***", "search_query_id": search_query_id, "reason": reason},
            error_payload=err,
        )
        _save("request_logs.json", logs)
        return err

    idx = None
    qry = None
    for i, q in enumerate(queries):
        if q.get("id") == search_query_id and q.get("api_key_id") == api_key_id:
            idx = i
            qry = q
            break
    if qry is None:
        err = _err("NOT_FOUND", "Search query not found.")
        _append_log(
            logs,
            api_key_id=api_key_id,
            tool_name="google_search",
            request_payload={"api_key": "***", "search_query_id": search_query_id, "reason": reason},
            error_payload=err,
        )
        _save("request_logs.json", logs)
        return err

    status = qry.get("status")
    transitions = {"queued": ["running", "cancelled"], "running": ["succeeded", "failed", "cancelled"], "succeeded": [], "failed": [], "cancelled": []}
    if status not in ("queued", "running"):
        err = _err("CONFLICT", "Job is not cancellable in its current status.", status=status)
        _append_log(
            logs,
            api_key_id=api_key_id,
            tool_name="google_search",
            request_payload={"api_key": "***", "search_query_id": search_query_id, "reason": reason},
            error_payload=err,
            search_query_id=search_query_id,
        )
        _save("request_logs.json", logs)
        return err
    if "cancelled" not in transitions.get(status, []):
        err = _err("INVALID_TRANSITION", "Cancellation is not allowed from current status.", from_status=status, to_status="cancelled")
        _append_log(
            logs,
            api_key_id=api_key_id,
            tool_name="google_search",
            request_payload={"api_key": "***", "search_query_id": search_query_id, "reason": reason},
            error_payload=err,
            search_query_id=search_query_id,
        )
        _save("request_logs.json", logs)
        return err

    # Apply transition
    updated = dict(qry)
    updated["status"] = "cancelled"
    updated["updated_at"] = now_iso
    updated["finished_at"] = now_iso
    if status == "queued":
        updated["started_at"] = updated.get("started_at")  # must remain null unless it actually started
    else:
        if updated.get("started_at") is None:
            updated["started_at"] = now_iso
    if reason:
        rp = updated.get("request_params")
        if isinstance(rp, dict):
            rp2 = dict(rp)
            rp2["_cancel_reason"] = reason
            rp2["_cancelled_at"] = now_iso
            updated["request_params"] = rp2

    queries[idx] = updated
    _save("search_queries.json", queries)

    # Key bookkeeping and request log
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    _save("api_keys.json", keys)

    resp = {"search_query": updated}
    _append_log(
        logs,
        api_key_id=api_key_id,
        tool_name="google_search",
        request_payload={"api_key": "***", "search_query_id": search_query_id, "reason": reason},
        response_payload=resp,
        error_payload=None,
        search_query_id=search_query_id,
    )
    _save("request_logs.json", logs)
    return resp

def list_scrape_jobs(api_key, status=None, created_from=None, created_to=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0418000" if __import__("os").path.isdir("./environment_mix/0418000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    def _find_api_key(keys, provided):
        if not isinstance(provided, str) or not provided.strip():
            return None
        p = provided.strip()
        for k in keys:
            if k.get("id") == p:
                return k
        for k in keys:
            if k.get("key_prefix") == p:
                return k
        return None

    def _rate_limited(logs, api_key_id, per_minute):
        if not isinstance(per_minute, int) or per_minute < 1:
            return True
        cutoff = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if r.get("api_key_id") != api_key_id:
                continue
            ca = _parse_dt(r.get("created_at"))
            if ca is None:
                continue
            if ca >= cutoff:
                cnt += 1
                if cnt >= per_minute:
                    return True
        return False

    def _new_id(prefix):
        import secrets
        alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567"
        return prefix + "".join(secrets.choice(alphabet) for _ in range(12))

    def _append_log(logs, api_key_id, tool_name, request_payload, response_payload=None, error_payload=None, search_query_id=None, scrape_job_id=None):
        log = {
            "id": _new_id("serper_log_"),
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "search_query_id": search_query_id,
            "scrape_job_id": scrape_job_id,
            "request_payload": request_payload if isinstance(request_payload, dict) else {},
            "response_payload": response_payload,
            "error_payload": error_payload,
            "latency_ms": max(0, int((time.time() - t0) * 1000)),
            "client_ip": None,
            "user_agent": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        logs.append(log)
        return log

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return None
        s = cur
        pad = "=" * ((4 - (len(s) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    # Validate
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string.")
    allowed_status = {"queued", "running", "succeeded", "failed", "cancelled"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            return _err("VALIDATION_ERROR", "status must be one of queued, running, succeeded, failed, cancelled.")
    dt_from = None
    dt_to = None
    if created_from is not None:
        dt_from = _parse_dt(created_from)
        if dt_from is None:
            return _err("VALIDATION_ERROR", "created_from must be an RFC3339 date-time string.")
    if created_to is not None:
        dt_to = _parse_dt(created_to)
        if dt_to is None:
            return _err("VALIDATION_ERROR", "created_to must be an RFC3339 date-time string.")
    if dt_from and dt_to and dt_from > dt_to:
        return _err("VALIDATION_ERROR", "created_from must be <= created_to.")
    if limit is not None:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer.")
        if limit < 1 or limit > 100:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 100.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    keys = _load("api_keys.json")
    jobs = _load("scrape_jobs.json")
    logs = _load("request_logs.json")

    key_row = _find_api_key(keys, api_key)
    if key_row is None:
        return _err("UNAUTHORIZED", "Invalid API key.")
    api_key_id = key_row.get("id")

    # Rate limit check (log violation)
    if _rate_limited(logs, api_key_id, key_row.get("rate_limit_per_minute")):
        err = _err("RATE_LIMIT", "Rate limit exceeded.")
        _append_log(logs, api_key_id, "scrape", {"status": status, "created_from": created_from, "created_to": created_to, "limit": limit, "cursor": cursor}, error_payload=err)
        _save("request_logs.json", logs)
        return err

    # Status check
    if key_row.get("status") != "active":
        err = _err("UNAUTHORIZED", "API key is not active.", status=key_row.get("status"))
        _append_log(logs, api_key_id, "scrape", {"status": status, "created_from": created_from, "created_to": created_to, "limit": limit, "cursor": cursor}, error_payload=err)
        _save("request_logs.json", logs)
        return err

    lim = limit if limit is not None else 20

    cur_obj = _decode_cursor(cursor) if cursor else None
    after_created_at = None
    after_id = None
    if cur_obj is not None:
        if not isinstance(cur_obj, dict) or cur_obj.get("api_key_id") != api_key_id:
            err = _err("VALIDATION_ERROR", "Invalid cursor.")
            _append_log(logs, api_key_id, "scrape", {"status": status, "created_from": created_from, "created_to": created_to, "limit": limit, "cursor": cursor}, error_payload=err)
            _save("request_logs.json", logs)
            return err
        after_created_at = _parse_dt(cur_obj.get("after_created_at")) if isinstance(cur_obj.get("after_created_at"), str) else None
        after_id = cur_obj.get("after_id")

    # Filter jobs
    rows = [j for j in jobs if j.get("api_key_id") == api_key_id]
    if status is not None:
        rows = [j for j in rows if j.get("status") == status]
    if dt_from is not None:
        rows = [j for j in rows if (_parse_dt(j.get("created_at")) is not None and _parse_dt(j.get("created_at")) >= dt_from)]
    if dt_to is not None:
        rows = [j for j in rows if (_parse_dt(j.get("created_at")) is not None and _parse_dt(j.get("created_at")) <= dt_to)]

    # Sort newest-first by created_at desc then id desc
    def _sort_key(j):
        ca = _parse_dt(j.get("created_at"))
        if ca is None:
            ca = datetime.datetime.min
        return (ca, str(j.get("id") or ""))
    rows.sort(key=_sort_key, reverse=True)

    if after_created_at is not None or after_id is not None:
        def _is_after(j):
            ca = _parse_dt(j.get("created_at"))
            if ca is None:
                ca = datetime.datetime.min
            jid = str(j.get("id") or "")
            if after_created_at is None:
                return True
            if ca < after_created_at:
                return True
            if ca > after_created_at:
                return False
            if after_id is None:
                return True
            return jid < str(after_id)
        rows = [j for j in rows if _is_after(j)]

    page = rows[:lim]
    has_more = len(rows) > lim
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _encode_cursor({
            "api_key_id": api_key_id,
            "after_created_at": last.get("created_at"),
            "after_id": last.get("id"),
        })

    out = {
        "scrape_jobs": page,
        "page": {
            "limit": lim,
            "total": len([j for j in jobs if j.get("api_key_id") == api_key_id and (status is None or j.get("status") == status)]),
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }

    # Update key last_used_at on success
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    _save("api_keys.json", keys)

    _append_log(logs, api_key_id, "scrape", {"status": status, "created_from": created_from, "created_to": created_to, "limit": limit, "cursor": cursor}, response_payload=out)
    _save("request_logs.json", logs)

    return out

def cancel_scrape_job(api_key, scrape_job_id, reason=None, **_extra):
    import json, os, datetime, time, secrets, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0418000" if __import__("os").path.isdir("./environment_mix/0418000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_utc = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now_utc.isoformat().replace("+00:00", "Z")

    def _lat_ms():
        return max(0, int((time.time() - t0) * 1000))

    def _new_id(prefix):
        alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567"
        return prefix + "".join(secrets.choice(alphabet) for _ in range(20))

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _minute_bucket(dt):
        return dt.replace(second=0, microsecond=0)

    def _rate_limited(log_rows, api_key_id, rate_limit_per_minute):
        if not isinstance(rate_limit_per_minute, int) or rate_limit_per_minute < 1:
            rate_limit_per_minute = 60
        bucket = _minute_bucket(now_utc)
        cnt = 0
        for r in log_rows:
            if r.get("api_key_id") != api_key_id:
                continue
            ts = _parse_dt(r.get("created_at"))
            if ts is None:
                continue
            if _minute_bucket(ts) == bucket:
                cnt += 1
        return cnt >= rate_limit_per_minute

    def _append_log(logs, api_key_id, tool_name, request_payload, response_payload=None, error_payload=None, search_query_id=None, scrape_job_id=None):
        log = {
            "id": _new_id("serper_log_"),
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "search_query_id": search_query_id,
            "scrape_job_id": scrape_job_id,
            "request_payload": request_payload if isinstance(request_payload, dict) else {},
            "response_payload": response_payload,
            "error_payload": error_payload,
            "latency_ms": _lat_ms(),
            "client_ip": None,
            "user_agent": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        logs.append(log)
        return log

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("UNAUTHORIZED", "Missing or invalid api_key.")
    if not isinstance(scrape_job_id, str) or not re.match(r"^serper_scrp_[0-9A-Z]{10,}$", scrape_job_id):
        return _err("VALIDATION_ERROR", "Invalid scrape_job_id.", field="scrape_job_id")
    if reason is not None:
        if not isinstance(reason, str):
            return _err("VALIDATION_ERROR", "reason must be a string.", field="reason")
        if len(reason) > 500:
            return _err("VALIDATION_ERROR", "reason exceeds maxLength 500.", field="reason")

    keys = _load("api_keys.json")
    jobs = _load("scrape_jobs.json")
    logs = _load("request_logs.json")

    provided = api_key.strip()
    key_row = None
    for k in keys:
        if k.get("id") == provided or k.get("key_prefix") == provided:
            key_row = k
            break
    if key_row is None:
        return _err("UNAUTHORIZED", "Invalid api_key.")
    api_key_id = key_row.get("id")

    if _rate_limited(logs, api_key_id, key_row.get("rate_limit_per_minute")):
        err = _err("RATE_LIMIT", "Rate limit exceeded.")
        _append_log(
            logs,
            api_key_id=api_key_id,
            tool_name="scrape",
            request_payload={"api_key": "***", "scrape_job_id": scrape_job_id, "reason": reason},
            error_payload=err,
        )
        _save("request_logs.json", logs)
        return err

    if key_row.get("status") != "active":
        err = _err("UNAUTHORIZED", "API key is not active.", status=key_row.get("status"))
        _append_log(
            logs,
            api_key_id=api_key_id,
            tool_name="scrape",
            request_payload={"api_key": "***", "scrape_job_id": scrape_job_id, "reason": reason},
            error_payload=err,
        )
        _save("request_logs.json", logs)
        return err

    idx = None
    job = None
    for i, j in enumerate(jobs):
        if j.get("id") == scrape_job_id and j.get("api_key_id") == api_key_id:
            idx = i
            job = j
            break
    if job is None:
        err = _err("NOT_FOUND", "Scrape job not found.")
        _append_log(
            logs,
            api_key_id=api_key_id,
            tool_name="scrape",
            request_payload={"api_key": "***", "scrape_job_id": scrape_job_id, "reason": reason},
            error_payload=err,
        )
        _save("request_logs.json", logs)
        return err

    status = job.get("status")
    transitions = {"queued": ["running", "cancelled"], "running": ["succeeded", "failed", "cancelled"], "succeeded": [], "failed": [], "cancelled": []}
    if status not in ("queued", "running"):
        err = _err("CONFLICT", "Job is not cancellable in its current status.", status=status)
        _append_log(
            logs,
            api_key_id=api_key_id,
            tool_name="scrape",
            request_payload={"api_key": "***", "scrape_job_id": scrape_job_id, "reason": reason},
            error_payload=err,
            scrape_job_id=scrape_job_id,
        )
        _save("request_logs.json", logs)
        return err
    if "cancelled" not in transitions.get(status, []):
        err = _err("INVALID_TRANSITION", "Cancellation is not allowed from current status.", from_status=status, to_status="cancelled")
        _append_log(
            logs,
            api_key_id=api_key_id,
            tool_name="scrape",
            request_payload={"api_key": "***", "scrape_job_id": scrape_job_id, "reason": reason},
            error_payload=err,
            scrape_job_id=scrape_job_id,
        )
        _save("request_logs.json", logs)
        return err

    updated = dict(job)
    updated["status"] = "cancelled"
    updated["updated_at"] = now_iso
    updated["finished_at"] = now_iso
    if status == "running" and updated.get("started_at") is None:
        updated["started_at"] = now_iso

    if reason:
        rp = updated.get("request_params")
        if isinstance(rp, dict):
            rp2 = dict(rp)
            rp2["_cancel_reason"] = reason
            rp2["_cancelled_at"] = now_iso
            updated["request_params"] = rp2

    jobs[idx] = updated
    _save("scrape_jobs.json", jobs)

    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    _save("api_keys.json", keys)

    resp = {"scrape_job": updated}
    _append_log(
        logs,
        api_key_id=api_key_id,
        tool_name="scrape",
        request_payload={"api_key": "***", "scrape_job_id": scrape_job_id, "reason": reason},
        response_payload=resp,
        error_payload=None,
        scrape_job_id=scrape_job_id,
    )
    _save("request_logs.json", logs)
    return resp
